diagram.source:
@startuml
class Deck {
  +name : String
  +render() : Pptx
}
class Slide {
  +title : String
}
interface Block
class Chart
class Diagram
Deck "1" *-- "many" Slide : holds
Slide o-- Block
Chart ..|> Block
Diagram ..|> Block
@enduml

@startuml
start
:Write the brief;
if (Approved?) then (yes)
  :Build the deck;
else (no)
  :Revise it;
endif
stop
@enduml

@startuml
left to right direction
actor Presenter
actor Reviewer
rectangle OPF {
  usecase (Write a deck) as Write
  usecase (Review a deck) as Review
  usecase (Export) as Export
}
Presenter --> Write
Reviewer --> Review
Write ..> Export : <<include>>
@enduml

@startuml
left to right direction
package "Front end" {
  [Editor]
  [Site]
}
node Server {
  [API]
  database "Decks" as DB
}
[Editor] --> [API] : REST
[Site] --> [API] : REST
[API] --> DB
@enduml
